import React, { useEffect, useRef, useState } from "react";
import { useNavigation, useFocusEffect } from "@react-navigation/native";
import {
  StyleSheet,
  View,
  ScrollView,
  Text,
  FlatList,
  Picker,
  TouchableOpacity,
} from "react-native";
import { Icon, Avatar, Image, Input, Button } from "react-native-elements";
import initialState from "../../utils/user";
import axios from "axios";
import lang from "../../utils/language";
import Toast from "react-native-root-toast";

export default function editProfile(props) {
  // validaciones al actualizar un usuario
  const { toastRef, setIsLoading, navigation } = props;
  const [name, setName] = useState(initialState.username);
  const [lastName, setLastName] = useState(initialState.lastname);
  const [empresa, setEmpresa] = useState(initialState.empresa);
  const [cargo, setCargo] = useState(initialState.cargo);
  const [actividad, setActividad] = useState(initialState.actividad);
  const [language, setlanguage] = useState(lang.idioma);
  const [idiomaUser, setIdiomaUser] = useState(initialState.idioma);
  const [country, setCountry] = useState(initialState.country);

  useEffect(() => {
    ListCargos();
    ListActividades();
    ListIdiomas();
    ListPaises();
  }, []);

  const [cargos, setCargos] = useState([]);

  function ListCargos() {
    const response = fetch(
      `https://socialagri.com/agriFM/wp-content/themes/agriFM/laptop/ajax/cargo-app.php`,
      {
        method: "GET",
        headers: { "Content-Type": "application/json" },
      }
    )
      .then((response) => response.json())
      .then((response) => {
        //console.log(response);
        setCargos(response);
      });
  }

  const [actividades, setActividades] = useState([]);

  function ListActividades() {
    const response = fetch(
      `https://socialagri.com/agriFM/wp-content/themes/agriFM/laptop/ajax/actividad-app.php`,
      {
        method: "GET",
        headers: { "Content-Type": "application/json" },
      }
    )
      .then((response) => response.json())
      .then((response) => {
        //console.log(response);
        setActividades(response);
      });
  }

  const [idiomas, setIdiomas] = useState([]);

  function ListIdiomas() {
    const response = fetch(
      `https://socialagri.com/agriFM/wp-content/themes/agriFM/laptop/ajax/idioma-app.php`,
      {
        method: "GET",
        headers: { "Content-Type": "application/json" },
      }
    )
      .then((response) => response.json())
      .then((response) => {
        //console.log(response);
        setIdiomas(response);
      });
  }

  const [paises, setPaises] = useState([]);

  function ListPaises() {
    const response = fetch(
      `https://socialagri.com/agriFM/wp-content/themes/agriFM/laptop/ajax/country-app.php`,
      {
        method: "GET",
        headers: { "Content-Type": "application/json" },
      }
    )
      .then((response) => response.json())
      .then((response) => {
        //console.log(response);
        setPaises(response);
      });
  }

  const UpdateUser = () => {
    axios
      .get(
        `https://socialagri.com/agriFM/wp-content/themes/agriFM/laptop/ajax/editprofile-app.php?id_user=${initialState.userID}&name_user=${name}&lastname_user=${lastName}&empresa=${empresa}&cargo=${cargo}&actividad=${actividad}&idioma=${idiomaUser}&country=${country}`
      )
      .then(function (response) {
        console.log(response.data[0].validation);
        if (response.data[0].validation === "ok") {
          initialState.username = name;
          initialState.lastname = lastName;
          initialState.empresa = empresa;
          initialState.cargo = cargo;
          initialState.actividad = actividad;
          initialState.idioma = idiomaUser;
          initialState.country = country;
          navigation.navigate("account");
          initialState.misIntereses = [];

          Toast.show("Perfil de usuarió actualizado", {
            position: Toast.positions.CENTER,
          });
        }
      })

      .then(function () {});
  };

  const PickerCargos = () => {};

  return (
    <ScrollView style={{ backgroundColor: "#422c5e" }}>
      <FormAdd
        setName={setName}
        setLastName={setLastName}
        setEmpresa={setEmpresa}
      />
      <View
        style={{
          flex: 1,
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <View style={{ width: "95%", marginBottom: 5 }}>
          <Text style={styles.labelTitle}>Cargo</Text>
        </View>
        <View style={styles.pickerContainer}>
          <Picker
            selectedValue={cargo}
            style={{ width: "95%", color: "#fff" }}
            onValueChange={(itemValue) => setCargo(itemValue)}
          >
            {cargos.map((l, i) => (
              <Picker.Item
                color="#422c5e"
                label={language === "es" ? l.nombrees : l.nombrept}
                value={l.id}
              />
            ))}
          </Picker>
        </View>
        <View style={{ width: "95%", marginBottom: 5 }}>
          <Text style={styles.labelTitle}>Actividad</Text>
        </View>
        <View style={styles.pickerContainer}>
          <Picker
            selectedValue={actividad}
            style={{ width: "95%", color: "#fff" }}
            onValueChange={(itemValue) => setActividad(itemValue)}
          >
            {actividades.map((l, i) => (
              <Picker.Item
                color="#422c5e"
                label={language === "es" ? l.nombrees : l.nombrept}
                value={l.id}
              />
            ))}
          </Picker>
        </View>
        <View style={{ width: "95%", marginBottom: 5 }}>
          <Text style={styles.labelTitle}>Idioma</Text>
        </View>
        <View style={styles.pickerContainer}>
          <Picker
            selectedValue={idiomaUser}
            style={{ width: "95%", color: "#fff" }}
            onValueChange={(itemValue) => setIdiomaUser(itemValue)}
          >
            {idiomas.map((l, i) => (
              <Picker.Item
                color="#422c5e"
                label={language === "es" ? l.nombrees : l.nombrept}
                value={l.id}
              />
            ))}
          </Picker>
        </View>
        <View style={{ width: "95%", marginBottom: 5 }}>
          <Text style={styles.labelTitle}>País</Text>
        </View>
        <View style={styles.lastPickerContainer}>
          <Picker
            selectedValue={country}
            style={{ width: "95%", color: "#fff" }}
            onValueChange={(itemValue) => setCountry(itemValue)}
          >
            {paises.map((l, i) => (
              <Picker.Item
                color="#422c5e"
                label={language === "es" ? l.nombrees : l.nombrept}
                value={l.id}
              />
            ))}
          </Picker>
        </View>
      </View>
      <Button
        title="Actualizar Perfil"
        buttonStyle={styles.btnStyle}
        onPress={UpdateUser}
      />
      <View style={{ height: 100 }}></View>
    </ScrollView>
  );
}

function FormAdd(props) {
  const { setName, setLastName, setEmpresa } = props;

  return (
    <View style={styles.viewForm}>
      <Text style={styles.labelTitle}>Nombre</Text>
      <Input
        placeholder="Nombre del usuario"
        containerStyle={styles.input}
        style={styles.placeholder}
        onChange={(e) => setName(e.nativeEvent.text)}
        defaultValue={initialState.username}
      />
      <Text style={styles.labelTitle}>Apellidos</Text>
      <Input
        placeholder="Apellidos"
        containerStyle={styles.input}
        style={styles.placeholder}
        onChange={(e) => setLastName(e.nativeEvent.text)}
        defaultValue={initialState.lastname}
      />
      <Text style={styles.labelTitle}>Empresa</Text>
      <Input
        placeholder="Empresa"
        containerStyle={styles.input}
        style={styles.placeholder}
        onChange={(e) => setEmpresa(e.nativeEvent.text)}
        defaultValue={initialState.empresa}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  logo: {
    width: "100%",
    height: 150,
    marginTop: 20,
  },
  placeholder: {
    fontWeight: "bold",
    color: "#fff",
  },
  labelTitle: {
    fontSize: 12,
    fontWeight: "bold",
    color: "#fff",
    marginLeft: 10,
  },
  pickerContainer: {
    width: "90%",
    alignItems: "center",
    backgroundColor: "#9a4dff",
    marginBottom: 20,
    borderBottomColor: "#fff",
    borderBottomWidth: 2,
  },
  lastPickerContainer: {
    width: "90%",
    alignItems: "center",
    backgroundColor: "#9a4dff",
    marginBottom: 30,
    borderBottomColor: "#fff",
    borderBottomWidth: 2,
  },
  viewContainer: {
    marginRight: 40,
    marginLeft: 40,
  },
  textRegister: {
    marginTop: 15,
    marginLeft: 10,
    marginRight: 10,
  },
  btnRegister: {
    color: "#93bf22",
    fontWeight: "bold",
  },
  btnStyle: {
    backgroundColor: "#93bf22",
    height: 50,
    marginLeft: 20,
    marginRight: 20,
  },
  divider: {
    backgroundColor: "#00a680",
    margin: 40,
  },
  viewForm: {
    marginLeft: 10,
    marginRight: 10,
    marginTop: 30,
  },
  input: {
    marginBottom: 10,
  },
});
